insert into public.shops (id, slug, name, categories, story, phone, address, city, state, lat, lng, hours, photo, status) values
  (md5('shop-crumb-craft')::uuid, 'crumb-and-craft', 'Crumb & Craft', '{"pastry","cookies"}'::text[], 'A downtown bake counter doing laminated dough in small morning batches. The brown-butter croissant sells out most Saturdays.', '(770) 555-0114', '24 S Main St', 'Alpharetta', 'GA', 34.0756, -84.2947, '{"mon":"7am–3pm","tue":"7am–3pm","wed":"7am–3pm","thu":"7am–3pm","fri":"7am–4pm","sat":"8am–4pm","sun":"8am–1pm"}'::jsonb, null, 'active'),
  (md5('shop-peach-state')::uuid, 'peach-state-scoops', 'Peach State Scoops', '{"ice_cream"}'::text[], 'Small-batch Georgia ice cream. Everything churned in-house, from brown-butter pecan to whatever the season hands them.', '(770) 555-0182', '118 Milton Ave', 'Alpharetta', 'GA', 34.0762, -84.2891, '{"mon":"Closed","tue":"12–9pm","wed":"12–9pm","thu":"12–9pm","fri":"12–10pm","sat":"11am–10pm","sun":"11am–8pm"}'::jsonb, null, 'active'),
  (md5('shop-cake-counter')::uuid, 'the-cake-counter', 'The Cake Counter', '{"cakes"}'::text[], 'Celebration cakes by the slice or the whole thing. Six layers, no shortcuts, and a rotating counter case that changes weekly.', '(770) 555-0147', '9 Roswell St', 'Alpharetta', 'GA', 34.0731, -84.2958, '{"mon":"9am–6pm","tue":"9am–6pm","wed":"9am–6pm","thu":"9am–6pm","fri":"9am–7pm","sat":"9am–7pm","sun":"Closed"}'::jsonb, null, 'active'),
  (md5('shop-butter-rye')::uuid, 'butter-and-rye', 'Butter & Rye', '{"pastry"}'::text[], 'Morning buns, rye shortbread, and a cardamom knot people drive across town for. Scandinavian-leaning, Georgia-sourced.', '(770) 555-0133', '402 Canton St', 'Alpharetta', 'GA', 34.0789, -84.2912, '{"mon":"Closed","tue":"7am–2pm","wed":"7am–2pm","thu":"7am–2pm","fri":"7am–2pm","sat":"8am–3pm","sun":"8am–1pm"}'::jsonb, null, 'active'),
  (md5('shop-sugar-line')::uuid, 'sugar-line-candy-co', 'Sugar Line Candy Co.', '{"candy"}'::text[], 'Old-school candy counter, new-school flavors. Hand-pulled taffy, dipped caramels, and a wall of nostalgic jars.', '(770) 555-0196', '57 N Broad St', 'Alpharetta', 'GA', 34.0771, -84.2965, '{"mon":"10am–7pm","tue":"10am–7pm","wed":"10am–7pm","thu":"10am–8pm","fri":"10am–8pm","sat":"10am–8pm","sun":"12–6pm"}'::jsonb, null, 'active'),
  (md5('shop-midnight-batch')::uuid, 'midnight-batch-cookies', 'Midnight Batch Cookies', '{"cookies"}'::text[], 'Warm cookies until late on weekends. Six permanent flavors, two rotating, one always stuffed with something unexpected.', '(770) 555-0128', '210 Academy St', 'Alpharetta', 'GA', 34.0742, -84.2889, '{"mon":"4–10pm","tue":"4–10pm","wed":"4–10pm","thu":"4–11pm","fri":"4pm–12am","sat":"12pm–12am","sun":"12–8pm"}'::jsonb, null, 'active')
insert into public.menu_items (id, shop_id, name, description, price_cents, category, flavor_tags, photo, available, bestseller, sort) values
  (md5('mi-cc-1')::uuid, md5('shop-crumb-craft')::uuid, 'Brown Butter Croissant', '72-hour laminated, nutty and shattering.', 525, 'pastry', '{"brown butter"}'::text[], null, true, true, 0),
  (md5('mi-cc-2')::uuid, md5('shop-crumb-craft')::uuid, 'Ube Cruffin', 'Croissant-muffin with ube custard and coconut sugar.', 650, 'pastry', '{"ube","coconut"}'::text[], null, true, true, 1),
  (md5('mi-cc-3')::uuid, md5('shop-crumb-craft')::uuid, 'Sea Salt Chocolate Chip', 'The classic, done right. Bittersweet pools, flaky salt.', 425, 'cookies', '{"chocolate","sea salt"}'::text[], null, true, false, 2),
  (md5('mi-cc-4')::uuid, md5('shop-crumb-craft')::uuid, 'Pistachio Morning Bun', 'Orange-zest sugar, Sicilian pistachio paste.', 575, 'pastry', '{"pistachio","orange"}'::text[], null, true, false, 3),
  (md5('mi-ps-1')::uuid, md5('shop-peach-state')::uuid, 'Brown Butter Pecan', 'Georgia pecans, toasted sugar, a little smoky.', 600, 'ice_cream', '{"brown butter","pecan"}'::text[], null, true, true, 4),
  (md5('mi-ps-2')::uuid, md5('shop-peach-state')::uuid, 'Peach Cobbler', 'Roasted peach ripple with oat streusel.', 600, 'ice_cream', '{"peach","oat"}'::text[], null, true, true, 5),
  (md5('mi-ps-3')::uuid, md5('shop-peach-state')::uuid, 'Miso Caramel', 'Sweet-salty, barely savory. Converts skeptics.', 600, 'ice_cream', '{"miso","caramel"}'::text[], null, true, false, 6),
  (md5('mi-ps-4')::uuid, md5('shop-peach-state')::uuid, 'Matcha Honey', 'Ceremonial matcha, wildflower honey.', 625, 'ice_cream', '{"matcha","honey"}'::text[], null, true, false, 7),
  (md5('mi-tc-1')::uuid, md5('shop-cake-counter')::uuid, 'Strawberry Rhubarb Slice', 'Vanilla bean layers, tart rhubarb jam.', 750, 'cakes', '{"strawberry","rhubarb","vanilla"}'::text[], null, true, true, 8),
  (md5('mi-tc-2')::uuid, md5('shop-cake-counter')::uuid, 'Chocolate Olive Oil Slice', 'Dark, fudgy, finished with flaky salt.', 700, 'cakes', '{"chocolate","sea salt"}'::text[], null, true, false, 9),
  (md5('mi-tc-3')::uuid, md5('shop-cake-counter')::uuid, 'Key Lime Icebox Cake', 'Cold, bright, graham-cracker crunch.', 700, 'cakes', '{"key lime","graham"}'::text[], null, true, false, 10),
  (md5('mi-tc-4')::uuid, md5('shop-cake-counter')::uuid, 'Whole Celebration Cake', 'Six layers, your pick of the week''s flavors. 48h notice.', 6800, 'cakes', '{}'::text[], null, true, false, 11),
  (md5('mi-br-1')::uuid, md5('shop-butter-rye')::uuid, 'Cardamom Knot', 'The one people drive across town for.', 550, 'pastry', '{"cardamom"}'::text[], null, true, true, 12),
  (md5('mi-br-2')::uuid, md5('shop-butter-rye')::uuid, 'Rye Shortbread', 'Dark rye, demerara crunch. Sold in threes.', 450, 'cookies', '{"rye"}'::text[], null, true, false, 13),
  (md5('mi-br-3')::uuid, md5('shop-butter-rye')::uuid, 'Blueberry Morning Bun', 'Wild blueberries, lemon glaze.', 525, 'pastry', '{"blueberry","lemon"}'::text[], null, true, false, 14),
  (md5('mi-sl-1')::uuid, md5('shop-sugar-line')::uuid, 'Sea Salt Caramels (6pc)', 'Hand-cut, slow-cooked, dipped to order.', 900, 'candy', '{"caramel","sea salt"}'::text[], null, true, true, 15),
  (md5('mi-sl-2')::uuid, md5('shop-sugar-line')::uuid, 'Pulled Taffy Bag', 'Rotating flavors — this week: peach + cream.', 650, 'candy', '{"peach","cream"}'::text[], null, true, false, 16),
  (md5('mi-sl-3')::uuid, md5('shop-sugar-line')::uuid, 'Honeycomb Toffee', 'Shattering, dark-chocolate dipped.', 750, 'candy', '{"honey","chocolate"}'::text[], null, true, false, 17),
  (md5('mi-mb-1')::uuid, md5('shop-midnight-batch')::uuid, 'The OG Chip', 'Brown butter dough, three chocolates, warm.', 500, 'cookies', '{"chocolate","brown butter"}'::text[], null, true, true, 18),
  (md5('mi-mb-2')::uuid, md5('shop-midnight-batch')::uuid, 'Pistachio White Chocolate', 'Salty-sweet, molten center.', 550, 'cookies', '{"pistachio","white chocolate"}'::text[], null, true, true, 19),
  (md5('mi-mb-3')::uuid, md5('shop-midnight-batch')::uuid, 'Stuffed Cookie of the Week', 'Ask what''s inside. It changes every Friday.', 600, 'cookies', '{"rotating"}'::text[], null, true, false, 20)
